This use of the comma operator is a bug. Each parenthesized expression `("format", args...)` evaluates to only its last operand via the comma operator, so `snprintf` receives just an integer/pointer as its `format` argument (not the string literal), and the format arguments are discarded. This will not compile the intended format and produces undefined behavior (passing a non-string as format). You need two separate `snprintf` calls, e.g.:

```c
} else if (c->querybuf) {
    if (server.hide_user_data_from_log) {
        snprintf(buf, sizeof(buf),
                 "Query buffer during protocol error: [hide_user_data_from_log]Redacted %zu bytes",
                 sdslen(c->querybuf) - c->qb_pos);
    } else {
        snprintf(buf, sizeof(buf),
                 "Query buffer during protocol error: '%.*s' (... more %zu bytes ...) '%.*s'",
                 PROTO_DUMP_LEN / 2, c->querybuf + c->qb_pos,
                 sdslen(c->querybuf) - c->qb_pos - PROTO_DUMP_LEN,
                 PROTO_DUMP_LEN / 2, c->querybuf + sdslen(c->querybuf) - PROTO_DUMP_LEN / 2);
    }
}
```

